// Mayéutica de las fichas del bloque 3, sub-bloque 3A · El shock (Marino caps. 14-17, en Cardiología → Merino
// Cardiología): fichas 1 mc-definiciones, 2 mc-vasopresores, 3 mc-hemorragico-clasificacion, 4 mc-hemorragico-fluidos,
// 5 mc-damage-control, 9 mc-inflamacion-ros, 10 mc-shock-septico, 11 mc-shock-toxico y 12 mc-anafilaxia. La pinta
// js/core/mayeutica.js (botón «Estudiar» del interruptor de cada ficha). Datos puros.
//
// Toda la medicina sale de la ficha (js/modules/cardiologia/merino-cardiologia.html) y de su PDF
// (docs/marino-2024-shock-caps14-17.pdf); cada pregunta dice dónde con `fuente` (ids `mc-…` de la ficha). Los pacientes
// se inventan (lista del bloque: Mateo, Amparo, Begoña y Nerea) y sus cuentas se marcan con `origen`. Plan: cobertura
// del bloque 3, §6.A y §7 (casos S1, S2, S4 y S5; cada caso se parte en un tramo por ficha, como Fermín en el bloque 2).
// Formato: el de b1-fluidos.js. `modeloVivo` abre un modelo que ya existe (río y mar, capilar, catéter, vaso, muralla,
// circulación viva) en el estado de la pregunta; `modelo`, la vista Visual de la ficha (el paso «Mira»).
// `modeloFuturo` es el estado del modelo que aún no está en la app (la cabecera del shock de la circulación viva, los
// receptores con el mastocito, las lupas nuevas del capilar, del río y mar, del catéter y del vaso); no se pinta: se
// conectará cuando el modelo exista.

const PDF = 'docs/marino-2024-shock-caps14-17.pdf';
const pag = (n, txt) => `<a class="biblio-link" href="${PDF}#page=${n}" target="_blank" rel="noopener">${txt || `PDF pág. ${n}`}</a>`;
// La vista Visual de una ficha de Merino Cardiología, como botón «modelo» (sale tras contestar).
const visual = (tab, texto) => ({ especialidad: 'cardiologia', view: 'merinoCardiologia', panel: 'panel-merino-cardio-tabs', tab, enVisual: '', texto });
// «Ver en la ficha» dentro de una nota (REGLAS §7.9): el enlace cruzado de siempre al párrafo exacto.
const enFicha = (tab, id) => ` <button type="button" class="may-ir" data-especialidad="cardiologia" data-view="merinoCardiologia" data-panel="panel-merino-cardio-tabs" data-tab="${tab}" data-resaltar="#${id}">Ver en la ficha ↗</button>`;
// La circulación viva (el ecógrafo) en un escenario que ya existe.
const eco = (escenario, texto) => ({ ecoEscenario: escenario, ecoVista: 'a4c', texto });

